                    /** @description Rate in basis points. `cdi_percent`: 100% of CDI = 10000 (1 to 30000). `prefixed` and `ipca_plus`: yearly rate, 12.5% = 1250 (prefixed 0 to 10000, ipca_plus 0 to 5000) */
                    rateBps: number;
